  (1, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t12","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TRONG SỐ NÀY","fontSize":44,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.2},{"id":"t13","type":"text","x":60,"y":157,"w":680,"rotation":0,"content":"Bản tin nội bộ của Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":false,"italic":true,"align":"center","lineHeight":1.62},{"id":"t14","type":"text","x":60,"y":221,"w":44,"rotation":0,"content":"03","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t15","type":"text","x":118,"y":221,"w":622,"rotation":0,"content":"Triển khai nhiệm vụ trọng tâm, chăm lo nhân dân","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t16","type":"text","x":60,"y":273,"w":44,"rotation":0,"content":"07","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t17","type":"text","x":118,"y":273,"w":622,"rotation":0,"content":"MTTQ phường lan toả nghĩa tình tri ân người có công","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t18","type":"text","x":60,"y":325,"w":44,"rotation":0,"content":"11","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t19","type":"text","x":118,"y":325,"w":622,"rotation":0,"content":"Cựu chiến binh dâng hương tưởng niệm các Anh hùng liệt sĩ","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t20","type":"text","x":60,"y":377,"w":44,"rotation":0,"content":"15","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t21","type":"text","x":118,"y":377,"w":622,"rotation":0,"content":"Đối thoại, lắng nghe tâm tư của người lao động","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t22","type":"text","x":60,"y":429,"w":44,"rotation":0,"content":"19","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t23","type":"text","x":118,"y":429,"w":622,"rotation":0,"content":"Đẩy nhanh giải phóng mặt bằng mở rộng Quốc lộ 6","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t24","type":"text","x":60,"y":481,"w":44,"rotation":0,"content":"23","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t25","type":"text","x":118,"y":481,"w":622,"rotation":0,"content":"Thăm hỏi lực lượng tuyên truyền giải phóng mặt bằng","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t26","type":"text","x":60,"y":533,"w":44,"rotation":0,"content":"27","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t27","type":"text","x":118,"y":533,"w":622,"rotation":0,"content":"Phụ nữ phường tổng vệ sinh Nghĩa trang Liệt sĩ","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t28","type":"text","x":60,"y":585,"w":44,"rotation":0,"content":"29","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t29","type":"text","x":118,"y":585,"w":622,"rotation":0,"content":"Giấy khen của Ban Chấp hành Đảng bộ phường","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t30","type":"text","x":60,"y":637,"w":680,"rotation":0,"content":"Nội dung và hình ảnh trong số này được tổng hợp từ các bài đã đăng trên Báo Hànộimới và fanpage của phường về hoạt động của Uỷ ban MTTQ Việt Nam phường Yên Nghĩa.","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":true,"align":"left","lineHeight":1.55}]'),
  (2, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t31","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"CÔNG TÁC MẶT TRẬN","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t32","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Phường Yên Nghĩa: Triển khai nhiều nhiệm vụ trọng tâm, hướng về cơ sở, chăm lo nhân dân","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t33","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Trọng Nguyễn · 16/07/2026 - 17:14 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i34","type":"image","x":60,"y":262,"w":680,"h":427,"rotation":0,"src":"/tin/bao/sau-thang-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t35","type":"text","x":60,"y":697,"w":680,"rotation":0,"content":"Các đại biểu tham dự hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t36","type":"text","x":60,"y":735,"w":680,"rotation":0,"content":"Chiều 16-7, Ủy ban MTTQ Việt Nam phường Yên Nghĩa tổ chức hội nghị đánh giá kết quả công tác Mặt trận 6 tháng đầu năm, triển khai nhiệm vụ trọng tâm 6 tháng cuối năm 2026 và phát động các hoạt động tuyên truyền kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27/7/1947-27/7/2026).","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (3, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i37","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/sau-thang-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t38","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Phó Bí thư Thường trực Đảng ủy phường Yên Nghĩa Phạm Văn Chiến phát biểu chỉ đạo tại hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t39","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Báo cáo tại hội nghị cho thấy, trong 6 tháng đầu năm 2026, Ủy ban MTTQ Việt Nam phường và các tổ chức thành viên đã bám sát nhiệm vụ chính trị của địa phương, triển khai hiệu quả các phong trào thi đua yêu nước, cuộc vận động và công tác an sinh xã hội.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t40","type":"text","x":60,"y":445,"w":680,"rotation":0,"content":"Hoạt động tuyên truyền, vận động nhân dân được đổi mới theo hướng thiết thực, hiệu quả...","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t41","type":"text","x":60,"y":536,"w":680,"rotation":0,"content":"MTTQ phường cũng tích cực tham gia công tác giải phóng mặt bằng các dự án trọng điểm, nhất là dự án cải tạo, nâng cấp Quốc lộ 6; đẩy mạnh hoạt động giám sát, phản biện xã hội; phát huy vai trò của ban thanh tra nhân dân, ban giám sát đầu tư của cộng đồng. Các hoạt động chuyển đổi số, xây dựng mô hình “Alo đoàn kết vì Yên Nghĩa hôm nay”, phong trào “Bình dân học vụ số” được duy trì, góp phần nâng cao hiệu quả tương tác giữa chính quyền với người dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t42","type":"text","x":60,"y":811,"w":680,"rotation":0,"content":"Tại hội nghị, các đại biểu đã tập trung thảo luận, đánh giá kết quả, đề xuất nhiều giải pháp nhằm nâng cao chất lượng hoạt động của Mặt trận ở cơ sở.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (4, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i43","type":"image","x":412,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/sau-thang-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t44","type":"text","x":412,"y":354,"w":328,"rotation":0,"content":"Quang cảnh hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t45","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Các tham luận nhấn mạnh vai trò của ban công tác Mặt trận trong công tác tuyên truyền, vận động nhân dân thực hiện chủ trương của Đảng, chính sách, pháp luật của Nhà nước; phát huy sức mạnh khối đại đoàn kết toàn dân;","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t46","type":"text","x":60,"y":398,"w":680,"rotation":0,"content":"tăng cường ứng dụng công nghệ số trong tuyên truyền, nắm bắt tình hình dư luận tại địa bàn.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t47","type":"text","x":60,"y":489,"w":680,"rotation":0,"content":"Phát biểu chỉ đạo tại hội nghị, Phó Bí thư Thường trực Đảng ủy phường Yên Nghĩa Phạm Văn Chiến biểu dương những kết quả mà Ủy ban MTTQ Việt Nam phường và các tổ chức thành viên đã đạt được trong thời gian qua. Đồng chí đề nghị, thời gian tới, MTTQ phường tiếp tục phát huy vai trò nòng cốt trong xây dựng khối đại đoàn kết toàn dân; nâng cao chất lượng công tác giám sát, phản biện xã hội; chủ động nắm bắt tình hình nhân dân, kịp thời tham mưu giải quyết các vấn đề phát sinh từ cơ sở.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t48","type":"text","x":60,"y":801,"w":680,"rotation":0,"content":"Tập trung triển khai hiệu quả các nhiệm vụ trọng tâm của thành phố và địa phương, trong đó có đợt cao điểm chuyển đổi số, các hoạt động hướng tới kỷ niệm 80 năm Ngày Thương binh - Liệt sĩ, công tác tìm","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (5, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t49","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"kiếm, quy tập, xác định danh tính hài cốt liệt sĩ; phối hợp thực hiện tốt công tác giải phóng mặt bằng, góp phần bảo đảm tiến độ các dự án trên địa bàn.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i50","type":"image","x":60,"y":222,"w":680,"h":560,"rotation":0,"src":"/tin/bao/sau-thang-4.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t51","type":"text","x":60,"y":790,"w":680,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh phát biểu tại hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (6, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t52","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Thay mặt Ban Thường trực Ủy ban MTTQ Việt Nam phường, Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh tiếp thu đầy đủ ý kiến chỉ đạo của lãnh đạo Đảng ủy phường và khẳng định sẽ cụ thể hóa các nhiệm vụ thành chương trình, kế hoạch hành động phù hợp với thực tiễn địa phương; tiếp tục đổi mới nội dung, phương thức hoạt động, hướng mạnh về cơ sở, chăm lo tốt hơn đời sống nhân dân, phát huy vai trò của MTTQ trong xây dựng Đảng, chính quyền vững mạnh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t53","type":"text","x":60,"y":371,"w":680,"rotation":0,"content":"Cũng tại hội nghị, Ủy ban MTTQ Việt Nam phường đã triển khai kế hoạch tuyên truyền và tổ chức các hoạt động kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t54","type":"text","x":60,"y":497,"w":680,"rotation":0,"content":"TRI ÂN NGƯỜI CÓ CÔNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t55","type":"text","x":60,"y":534,"w":680,"rotation":0,"content":"MTTQ phường Yên Nghĩa lan tỏa nghĩa tình tri ân người có công","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t56","type":"text","x":60,"y":624,"w":680,"rotation":0,"content":"Văn Trọng · 24/07/2026 - 16:27 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (7, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t57","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Nhân kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27/7/1947 – 27/7/2026), cùng với các hoạt động thăm hỏi, tặng quà người có công trên địa bàn, Ủy ban MTTQ Việt Nam phường Yên Nghĩa đã phát huy vai trò nòng cốt trong việc tập hợp các tổ chức chính trị - xã hội triển khai nhiều hoạt động tri ân thiết thực, góp phần lan tỏa đạo lý \"Uống nước nhớ nguồn\", \"Đền ơn đáp nghĩa\" trong cộng đồng.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55},{"id":"i58","type":"image","x":60,"y":372,"w":680,"h":495,"rotation":0,"src":"/tin/bao/tri-an-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t59","type":"text","x":60,"y":875,"w":680,"rotation":0,"content":"Đại diện Hội Liên hiệp Phụ nữ phường Yên Nghĩa thăm, tặng quà Mẹ liệt sĩ nhân dịp 27-7. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (8, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i60","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/tri-an-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t61","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Hoạt động tri ân của các tổ chức thành viên MTTQ phường Yên Nghĩa góp phần chăm lo đời sống người có công với cách mạng. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t62","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Những ngày tháng Bảy, không khí tri ân hiện diện ở nhiều khu dân cư của phường Yên Nghĩa.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t63","type":"text","x":60,"y":469,"w":680,"rotation":0,"content":"Các tổ chức thành viên của Mặt trận đã đồng loạt triển khai chương trình thăm hỏi, tặng quà các Mẹ Việt Nam Anh hùng, thương binh, bệnh binh, cựu thanh niên xung phong và gia đình chính sách với sự trân trọng, chu đáo.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t64","type":"text","x":60,"y":634,"w":680,"rotation":0,"content":"Các tổ chức thành viên của MTTQ Việt Nam phường Yên Nghĩa đồng loạt triển khai hoạt động tri ân người có công. Hội Liên hiệp Phụ nữ, Đoàn Thanh niên và Hội Cựu chiến binh đã trao nhiều phần quà tới Mẹ Việt Nam Anh hùng, cựu thanh niên xung phong, thương binh và gia đình chính sách, góp phần lan tỏa đạo lý \"Uống nước nhớ nguồn\".","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (9, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t65","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Các hoạt động được triển khai đồng bộ, phù hợp với điều kiện thực tế của từng tổ chức thành viên, tạo nên sức lan tỏa sâu rộng trong cộng đồng. Qua đó, tiếp tục khẳng định vai trò của MTTQ Việt Nam phường trong việc tập hợp, phát huy sức mạnh khối đại đoàn kết toàn dân, chăm lo đời sống vật chất, tinh thần cho người có công với cách mạng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t66","type":"text","x":60,"y":296,"w":680,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh cho biết, các hoạt động tri ân nhân dịp 27-7 không chỉ là việc làm thường niên mà còn là trách nhiệm, tình cảm và đạo lý của cả hệ thống chính trị đối với những người đã cống hiến, hy sinh vì Tổ quốc.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t67","type":"text","x":60,"y":459,"w":680,"rotation":0,"content":"\"Bằng những phần việc cụ thể, Mặt trận cùng các tổ chức thành viên mong muốn góp phần chăm lo tốt hơn đời sống người có công, đồng thời giáo dục truyền thống yêu nước, lòng biết ơn cho thế hệ trẻ. Chúng tôi xác định công tác ''Đền ơn đáp nghĩa'' phải được thực hiện thường xuyên, liên tục, trở thành nét đẹp trong đời sống cộng đồng và là động lực để củng cố khối đại đoàn kết toàn dân\", bà Lương Huệ Minh chia sẻ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t68","type":"text","x":60,"y":697,"w":680,"rotation":0,"content":"Theo bà Lương Huệ Minh, bên cạnh việc huy động nguồn lực xã hội hóa để chăm lo người có công, MTTQ phường sẽ tiếp tục phối hợp chặt chẽ với các tổ chức thành viên, các khu dân cư nắm bắt tâm tư, nguyện vọng của các gia đình chính sách, kịp thời đề xuất cấp ủy, chính quyền giải quyết những khó khăn phát sinh, bảo đảm không để người có công nào bị bỏ lại phía sau.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (10, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t69","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Thông qua chuỗi hoạt động tri ân dịp 27-7, tinh thần \"Uống nước nhớ nguồn\" tiếp tục được lan tỏa sâu rộng trên địa bàn phường Yên Nghĩa. Đây cũng là dịp để mỗi cán bộ, đoàn viên, hội viên và các tầng lớp nhân dân ôn lại truyền thống đấu tranh vẻ vang của dân tộc, bồi đắp lòng yêu nước, ý thức trách nhiệm đối với cộng đồng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t70","type":"text","x":60,"y":296,"w":680,"rotation":0,"content":"Những phần quà tuy giá trị vật chất không lớn nhưng chứa đựng tình cảm, sự biết ơn và trách nhiệm của cả hệ thống chính trị và nhân dân địa phương đối với những người đã hy sinh, cống hiến vì nền độc lập, tự do của Tổ quốc. Qua đó, góp phần xây dựng phường Yên Nghĩa ngày càng đoàn kết, nghĩa tình, phát huy truyền thống cách mạng, chung sức xây dựng quê hương phát triển bền vững.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t71","type":"text","x":60,"y":534,"w":680,"rotation":0,"content":"TRI ÂN NGƯỜI CÓ CÔNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t72","type":"text","x":60,"y":571,"w":680,"rotation":0,"content":"Hội Cựu chiến binh phường Yên Nghĩa dâng hương tưởng niệm các Anh hùng liệt sĩ","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t73","type":"text","x":60,"y":661,"w":680,"rotation":0,"content":"Văn Trọng · 23/07/2026 - 16:56 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t74","type":"text","x":60,"y":700,"w":680,"rotation":0,"content":"Nhân kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27-7-1947 – 27-7-2026), chiều 23-7, Hội Cựu chiến binh phường Yên Nghĩa đã tổ chức lễ dâng hương, dâng hoa tưởng niệm các Anh hùng liệt sĩ tại Tượng đài Chiến thắng và các Đài tưởng niệm Nghĩa trang Liệt sĩ trên địa bàn phường, đồng thời gặp mặt, tri ân đại diện Hợp tác xã Thương binh 27-7","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (11, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t75","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"và triển khai nhiệm vụ trọng tâm công tác Hội thời gian tới.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55},{"id":"i76","type":"image","x":60,"y":149,"w":680,"h":520,"rotation":0,"src":"/tin/bao/ccb-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t77","type":"text","x":60,"y":677,"w":680,"rotation":0,"content":"Hội Cựu chiến binh phường Yên Nghĩa tổ chức lễ dâng hương, dâng hoa tưởng niệm các Anh hùng liệt sĩ. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t78","type":"text","x":60,"y":739,"w":680,"rotation":0,"content":"Dự chương trình có đại diện Hội Cựu chiến binh thành phố; lãnh đạo Đảng ủy, HĐND, UBND, Ủy ban MTTQ Việt Nam phường Yên Nghĩa cùng đông đảo cán bộ, hội viên Hội Cựu chiến binh và các đại biểu khách mời.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (12, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i79","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/ccb-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t80","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Những người lính năm xưa thành kính thắp nén hương tri ân đồng đội đã ngã xuống vì sự nghiệp bảo vệ Tổ quốc. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t81","type":"text","x":60,"y":445,"w":680,"rotation":0,"content":"Trong không khí trang nghiêm, các đại biểu thành kính dâng hương, dâng hoa, dành phút mặc niệm tưởng nhớ Chủ tịch Hồ Chí Minh, các Anh hùng liệt sĩ, các Mẹ Việt Nam Anh hùng và những người con ưu tú của dân tộc đã anh dũng chiến đấu, hy sinh vì độc lập, tự do của Tổ quốc. Những nén hương thơm thể hiện lòng biết ơn sâu sắc, đồng thời nhắc nhở các thế hệ hôm nay tiếp tục phát huy truyền thống cách mạng, chung sức xây dựng quê hương ngày càng giàu đẹp, văn minh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t82","type":"text","x":60,"y":720,"w":680,"rotation":0,"content":"Ông Lê Ngọc Ninh, cựu chiến binh từng chiến đấu tại mặt trận Vị Xuyên, không giấu được xúc động: \" Có những đồng đội mãi mãi dừng lại ở tuổi đôi mươi. Mỗi lần thắp nén hương tri ân, tôi như thấy họ vẫn đang ở bên mình.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (13, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i83","type":"image","x":412,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/ccb-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t84","type":"text","x":412,"y":354,"w":328,"rotation":0,"content":"Chủ tịch Hội Cựu chiến binh phường Yên Nghĩa Đoàn Viết Mạnh dâng hương tưởng niệm các Anh hùng liệt sĩ tại Nghĩa trang Liệt sĩ phường. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t85","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Đây không chỉ là hoạt động tưởng nhớ những người đã ngã xuống mà còn là dịp để những cựu chiến binh như chúng tôi nhắc nhau tiếp tục phát huy phẩm chất Bộ đội Cụ Hồ, giáo dục con cháu về truyền thống yêu nước\".","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t86","type":"text","x":60,"y":469,"w":680,"rotation":0,"content":"Chủ tịch Hội Cựu chiến binh phường Yên Nghĩa Đoàn Viết Mạnh cho biết, hoạt động dâng hương và tri ân là dịp để cán bộ, hội viên bày tỏ lòng biết ơn đối với sự hy sinh to lớn của các thế hệ cha anh, đồng thời giáo dục truyền thống yêu nước, đạo lý \"Uống nước nhớ nguồn\" cho thế hệ trẻ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t87","type":"text","x":60,"y":669,"w":680,"rotation":0,"content":"Theo ông Đoàn Viết Mạnh, thời gian tới, Hội sẽ tiếp tục phát huy vai trò nòng cốt của hội viên trong tuyên truyền, vận động nhân dân thực hiện tốt các chủ trương của Đảng, chính sách, pháp luật của Nhà nước; tích cực tham gia xây dựng đô thị văn minh, giữ gìn an ninh trật tự, bảo vệ môi trường và các phong trào thi đua tại địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (14, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t88","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Cùng ngày, Hội Cựu chiến binh phường tổ chức hội nghị Ban Chấp hành mở rộng kết hợp gặp mặt, tri ân đại diện Hợp tác xã Thương binh 27-7. Tại chương trình, Hội đã trao những phần quà ý nghĩa, động viên các thương binh tiếp tục phát huy phẩm chất Bộ đội Cụ Hồ, gương mẫu trong các phong trào thi đua yêu nước, tích cực tham gia xây dựng hệ thống chính trị ở cơ sở và phát triển kinh tế - xã hội địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t89","type":"text","x":60,"y":334,"w":680,"rotation":0,"content":"ĐOÀN THỂ","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t90","type":"text","x":60,"y":371,"w":680,"rotation":0,"content":"Yên Nghĩa đối thoại, lắng nghe tâm tư của người lao động","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t91","type":"text","x":60,"y":461,"w":680,"rotation":0,"content":"Nguyễn Trọng · 31/07/2026 - 16:25 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t92","type":"text","x":60,"y":500,"w":680,"rotation":0,"content":"Sáng 31-7, Đảng ủy - HĐND - UBND - Ủy ban MTTQ Việt Nam phường Yên Nghĩa phối hợp với Công đoàn phường tổ chức Hội nghị gặp gỡ, tiếp xúc, đối thoại với đoàn viên, người lao động trên địa bàn năm 2026. Đây là diễn đàn để người đứng đầu cấp ủy, chính quyền trực tiếp lắng nghe tâm tư, nguyện vọng, kịp thời tháo gỡ những khó khăn, vướng mắc, góp phần phát huy dân chủ ở cơ sở và xây dựng quan hệ lao động hài hòa.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (15, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i93","type":"image","x":60,"y":96,"w":680,"h":520,"rotation":0,"src":"/tin/bao/cong-doan-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t94","type":"text","x":60,"y":624,"w":680,"rotation":0,"content":"Phó Bí thư Đảng ủy, Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn phát biểu tại Hội nghị gặp gỡ, tiếp xúc, đối thoại với đoàn viên, người lao động năm 2026. Ảnh:YN","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t95","type":"text","x":60,"y":686,"w":680,"rotation":0,"content":"Phó Bí thư Đảng ủy, Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn cho biết, hiện trên địa bàn có gần 1.500 đoàn viên, người lao động thuộc các công đoàn cơ sở khối trường học và doanh nghiệp. Đây là lực lượng quan trọng, đóng góp tích cực vào phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh của địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (16, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i96","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/cong-doan-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t97","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Hội nghị gặp gỡ, tiếp xúc, đối thoại giữa người đứng đầu cấp ủy, chính quyền với đoàn viên, người lao động trên địa bàn phường Yên Nghĩa. Ảnh:YN","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t98","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Tuy nhiên, đời sống của một bộ phận người lao động vẫn còn khó khăn; việc làm, thu nhập ở một số lĩnh vực chưa ổn định, trong khi các vấn đề về nhà ở, an sinh xã hội, trường học cho con em, thiết chế văn hóa, thể thao vẫn cần tiếp tục được quan tâm.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i99","type":"image","x":412,"y":469,"w":328,"h":250,"rotation":0,"src":"/tin/bao/cong-doan-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t100","type":"text","x":412,"y":727,"w":328,"rotation":0,"content":"Nhiều ý kiến, kiến nghị của đoàn viên, người lao động được lãnh đạo địa phương trao đổi, làm rõ ngay tại hội nghị. Ảnh: YN","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t101","type":"text","x":60,"y":469,"w":328,"rotation":0,"content":"Với tinh thần dân chủ, thẳng thắn và trách nhiệm, lãnh đạo phường đề nghị đoàn viên, người lao động tập trung trao đổi những nội dung liên quan đến việc làm, tiền lương, điều kiện lao động, chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp;","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t102","type":"text","x":60,"y":818,"w":680,"rotation":0,"content":"đồng thời phản ánh những vấn đề về nhà ở xã hội, vệ sinh môi trường, an ninh trật tự, an toàn giao thông và hoạt động của tổ chức công đoàn.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (17, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t103","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Các ý kiến, kiến nghị tại hội nghị được lãnh đạo UBND phường và các đơn vị liên quan trực tiếp trao đổi, giải đáp. Đối với những nội dung thuộc thẩm quyền, UBND phường giao các bộ phận chuyên môn tiếp thu, tham mưu giải quyết kịp thời; những vấn đề vượt thẩm quyền sẽ được tổng hợp, báo cáo cấp có thẩm quyền xem xét, xử lý theo quy định. Sau hội nghị, Công đoàn phường phối hợp với các đơn vị liên quan theo dõi, đôn đốc việc giải quyết, bảo đảm các kiến nghị chính đáng của đoàn viên, người lao động được trả lời đầy đủ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t104","type":"text","x":60,"y":408,"w":680,"rotation":0,"content":"Nhân dịp này, Ban Tổ chức đã trao quà cho đoàn viên, người lao động có hoàn cảnh khó khăn. Hoạt động không chỉ thể hiện sự quan tâm của cấp ủy, chính quyền và tổ chức công đoàn đối với người lao động mà còn góp phần củng cố niềm tin, tăng cường sự gắn kết giữa chính quyền với đoàn viên, người lao động, hướng tới xây dựng chính quyền phục vụ, gần dân và vì dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (18, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t105","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"VẬN ĐỘNG NHÂN DÂN","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t106","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Phường Yên Nghĩa đẩy nhanh tiến độ giải phóng mặt bằng dự án cải tạo, mở rộng Quốc lộ 6","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t107","type":"text","x":60,"y":264,"w":680,"rotation":0,"content":"Yên Nghĩa News · Nguồn: Fanpage phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i108","type":"image","x":60,"y":303,"w":680,"h":423,"rotation":0,"src":"/tin/bao/gpmb-tuyen-truyen-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t109","type":"text","x":60,"y":734,"w":680,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t110","type":"text","x":60,"y":772,"w":680,"rotation":0,"content":"Chiều ngày 07/7/2026, đồng chí Lê Xuân Hoàn - Chủ tịch UBND phường Yên Nghĩa cùng các đồng chí lãnh đạo phường đã trực tiếp kiểm tra, giám sát việc thi công tháo dỡ, giải phóng mặt bằng phục vụ Dự án cải tạo, mở rộng Quốc lộ 6.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (19, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i111","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/gpmb-tuyen-truyen-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t112","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t113","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Theo ghi nhận thực tế, đến nay đa số các hộ dân thuộc diện thu hồi đất đã đồng thuận, tích cực di chuyển tài sản, tháo dỡ công trình và bàn giao mặt bằng cho chủ đầu tư theo quy định.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t114","type":"text","x":60,"y":398,"w":680,"rotation":0,"content":"Sự đồng thuận, ủng hộ và chấp hành nghiêm các chủ trương, chính sách của Nhân dân là yếu tố quan trọng góp phần đẩy nhanh tiến độ thực hiện dự án, sớm hoàn thiện hạ tầng giao thông, tạo động lực phát triển kinh tế - xã hội của địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i115","type":"image","x":412,"y":561,"w":328,"h":250,"rotation":0,"src":"/tin/bao/gpmb-tuyen-truyen-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t116","type":"text","x":412,"y":819,"w":328,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t117","type":"text","x":60,"y":561,"w":328,"rotation":0,"content":"Phường Yên Nghĩa đang tập trung cao độ cho công tác giải phóng mặt bằng, phấn đấu hoàn thành việc bàn giao mặt bằng sạch theo đúng tiến độ Thành phố giao.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (20, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t118","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"UBND phường trân trọng cảm ơn sự phối hợp, đồng hành của các hộ gia đình, cá nhân trong quá trình triển khai dự án và mong tiếp tục nhận được sự đồng thuận của Nhân dân để dự án được thực hiện thuận lợi, hiệu quả.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i119","type":"image","x":60,"y":222,"w":680,"h":620,"rotation":0,"src":"/tin/bao/gpmb-tuyen-truyen-4.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t120","type":"text","x":60,"y":850,"w":680,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (21, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i121","type":"image","x":60,"y":96,"w":680,"h":620,"rotation":0,"src":"/tin/bao/gpmb-tuyen-truyen-5.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t122","type":"text","x":60,"y":724,"w":680,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (22, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t123","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"VẬN ĐỘNG NHÂN DÂN","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t124","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Uỷ ban MTTQ Việt Nam phường Yên Nghĩa thăm hỏi, động viên lực lượng tuyên truyền giải phóng mặt bằng Quốc lộ 6","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t125","type":"text","x":60,"y":264,"w":680,"rotation":0,"content":"Yên Nghĩa News · Nguồn: Fanpage phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i126","type":"image","x":60,"y":303,"w":680,"h":386,"rotation":0,"src":"/tin/bao/gpmb-tham-hoi-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t127","type":"text","x":60,"y":697,"w":680,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t128","type":"text","x":60,"y":735,"w":680,"rotation":0,"content":"Chiều ngày 07/7/2026, Ủy ban MTTQ Việt Nam phường Yên Nghĩa tổ chức buổi làm việc nhằm nắm bắt tình hình, động viên lực lượng Ban Công tác Mặt trận phối hợp với UBND phường thực hiện công tác tuyên truyền giải phóng mặt bằng tại Tổ dân phố Do Lộ.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (23, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i129","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/gpmb-tham-hoi-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t130","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t131","type":"text","x":60,"y":398,"w":680,"rotation":0,"content":"Tại buổi làm việc, đồng chí Lương Huệ Minh – Ủy viên Thường vụ Đảng ủy, Chủ tịch Ủy ban MTTQ Việt Nam phường đã thăm hỏi, động viên tinh thần các tổ công tác và trao tặng những phần quà nhằm khích lệ lực lượng đang trực tiếp tham gia tuyên truyền, vận động Nhân dân bàn giao mặt bằng sớm phục vụ công tác thực hiện GPMB QL6.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t132","type":"text","x":60,"y":600,"w":680,"rotation":0,"content":"Đại diện Chi bộ, Tổ dân phố Do Lộ và các tổ tuyên truyền của Đảng ủy đã báo cáo tình hình, tiến độ triển khai công tác vận động các hộ gia đình di dời tài sản, bàn giao mặt bằng để thực hiện Dự án cải tạo, mở rộng Quốc lộ 6.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t133","type":"text","x":60,"y":763,"w":680,"rotation":0,"content":"Phát biểu kết luận, đồng chí Chủ tịch UB MTTQ Việt Nam phường ghi nhận, biểu dương những kết quả mà các tổ công tác đã đạt được.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (24, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i134","type":"image","x":412,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/gpmb-tham-hoi-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t135","type":"text","x":412,"y":354,"w":328,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t136","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Đồng thời, đề nghị các đồng chí tiếp tục phát huy tinh thần trách nhiệm, tăng cường tuyên truyền, vận động để tạo sự đồng thuận trong Nhân dân, góp phần đẩy nhanh tiến độ giải phóng mặt bằng theo kế hoạch.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t137","type":"text","x":60,"y":398,"w":680,"rotation":0,"content":"Sự vào cuộc tích cực của các lực lượng và sự đồng thuận của Nhân dân là yếu tố quan trọng góp phần thực hiện thành công Dự án cải tạo, mở rộng Quốc lộ 6, vì sự phát triển chung của thủ đô và địa địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i138","type":"image","x":60,"y":524,"w":680,"h":367,"rotation":0,"src":"/tin/bao/gpmb-tham-hoi-4.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t139","type":"text","x":60,"y":899,"w":680,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
