  (26, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t142","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TRI ÂN NGƯỜI CÓ CÔNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t143","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Hội Liên hiệp Phụ nữ phường ra quân tổng vệ sinh môi trường tại Nghĩa trang Liệt sĩ","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t144","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Yên Nghĩa News · Nguồn: Fanpage phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i145","type":"image","x":60,"y":262,"w":680,"h":427,"rotation":0,"src":"/tin/bao/phu-nu-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t146","type":"text","x":60,"y":697,"w":680,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t147","type":"text","x":60,"y":735,"w":680,"rotation":0,"content":"Thiết thực hướng tới kỷ niệm Ngày Thương binh - Liệt sĩ 27/7, Sáng ngày 19/7 Hội LHPN phường Yên Nghĩa tổ chức ra quân tổng vệ sinh môi trường tại Nghĩa trang Liệt sĩ. Buổi hoạt động đã thu hút hơn 70 cán bộ, hội viên phụ nữ trên toàn địa bàn phường tham gia.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (27, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i148","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/phu-nu-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t149","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t150","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Với tấm lòng thành kính tri ân, các chị em đã cùng nhau quét dọn khuôn viên, nhổ cỏ, tỉa cây và chỉnh trang sạch sẽ từng phần mộ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t151","type":"text","x":60,"y":398,"w":680,"rotation":0,"content":"Nhờ sự chung tay nhiệt tình của mọi người, cảnh quan nghĩa trang đã nhanh chóng trở nên khang trang, sạch đẹp và thêm phần trang nghiêm.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t152","type":"text","x":60,"y":489,"w":680,"rotation":0,"content":"Đây là hoạt động thiết thực thể hiện đạo lý \"Uống nước nhớ nguồn\", bày tỏ lòng biết ơn sâu sắc của phụ nữ phường Yên Nghĩa đối với những hy sinh to lớn của các Anh hùng Liệt sĩ. Đồng thời, hoạt động cũng góp phần lan tỏa ý thức giữ gìn cảnh quan môi trường và giáo dục truyền thống yêu nước tại địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i153","type":"image","x":60,"y":689,"w":680,"h":202,"rotation":0,"src":"/tin/bao/phu-nu-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t154","type":"text","x":60,"y":899,"w":680,"rotation":0,"content":"Ảnh: Fanpage phường Yên Nghĩa.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
